"""Parse RFC 822 access requests, ignoring signatures and quoted replies."""
from __future__ import annotations

import email
import re
from dataclasses import dataclass
from email import policy as email_policy
from email.utils import getaddresses
from pathlib import Path

TICKET_RE = re.compile(r"\[(AR-\d+)\]")
FIELD_RE = re.compile(r"^([A-Za-z-]+)\s*:\s*(.*)$")
ACTIONS = ("grant", "revoke")


class ParseError(ValueError):
    """Malformed request, retaining envelope information for the audit log."""

    def __init__(self, reason: str, *, ticket="?", msg_id="", actor=""):
        super().__init__(reason)
        self.ticket = ticket
        self.msg_id = msg_id
        self.actor = actor


def normalize_sender(value: str) -> str:
    """Only a single mailbox can identify the request's sender."""
    addresses = getaddresses([value])
    if len(addresses) != 1:
        return ""
    address = addresses[0][1].strip().lower()
    if address.count("@") != 1 or any(c.isspace() for c in address):
        return ""
    local, domain = address.split("@")
    return address if local and domain else ""


@dataclass
class Request:
    path: Path
    msg_id: str
    ticket: str
    sender: str
    action: str
    principal: str
    roles: list[str]
    justification: str = ""
    authentication_failure: str = ""


def _plain_body(msg) -> str:
    part = msg.get_body(preferencelist=("plain",))
    if part is None:
        raise ParseError("no text/plain part")
    return part.get_content()


def parse_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for line in text.splitlines():
        if line.rstrip() == "--":
            break
        if line.lstrip().startswith(">"):
            continue
        m = FIELD_RE.match(line.strip())
        if m:
            fields.setdefault(m.group(1).lower(), m.group(2).strip())
    return fields


def _authentication_failure(msg) -> str:
    # Only consume results stamped by our receiving MX. Missing results are
    # allowed for older form messages; explicit failures need human review.
    for header in msg.get_all("Authentication-Results", []):
        authority, _, results = str(header).partition(";")
        if authority.strip().lower() != "mx.fernhollow.dev":
            continue
        failures = re.findall(
            r"\b(dmarc|spf|dkim)\s*=\s*(fail|permerror)\b", results, re.I)
        if failures:
            return "mail authentication failed: " + ", ".join(
                f"{method.lower()}={result.lower()}" for method, result in failures)
    return ""


def parse_message(path: Path) -> Request:
    with open(path, "rb") as fh:
        msg = email.message_from_binary_file(fh, policy=email_policy.default)
    subject = str(msg.get("Subject", ""))
    match = TICKET_RE.search(subject)
    ticket = match.group(1) if match else "?"
    msg_id = str(msg.get("Message-ID", "")).strip()
    senders = msg.get_all("From", [])
    sender = normalize_sender(str(senders[0])) if len(senders) == 1 else ""
    try:
        if not match:
            raise ParseError(f"no ticket id in subject {subject!r}")
        if not sender:
            raise ParseError("missing or ambiguous From mailbox")
        fields = parse_fields(_plain_body(msg))
        action = fields.get("action", "").lower()
        if action not in ACTIONS:
            raise ParseError(f"unsupported action {action!r}")
        principal = fields.get("principal", "")
        if not principal:
            raise ParseError("missing Principal")
        if not fields.get("roles"):
            raise ParseError("missing Roles")
        roles = [role.strip() for role in fields["roles"].split(",")]
        if not all(roles):
            raise ParseError("empty role in Roles")
        return Request(
            path=path, msg_id=msg_id, ticket=ticket, sender=sender,
            action=action, principal=principal, roles=list(dict.fromkeys(roles)),
            justification=fields.get("justification", ""),
            authentication_failure=_authentication_failure(msg),
        )
    except (ValueError, LookupError, TypeError) as exc:
        raise ParseError(str(exc), ticket=ticket, msg_id=msg_id, actor=sender) from exc
